module FactLastThreeDigits(\n    input clk,\n    input rst_n,\n    input start,\n    input [9:0] n,\n    output reg [9:0] result,\n    output reg done\n);\n    \n    // State definitions\n    localparam [2:0] \n        IDLE = 3'd0,\n        FACT_LOOP = 3'd1,\n        POWER_PREP = 3'd2,\n        POWER_LOOP = 3'd3,\n        MULTIPLY = 3'd4,\n        FINISH = 3'd5;\n    \n    reg [2:0] state;\n    \n    // Factorial computation registers\n    reg [13:0] product;\n    reg [9:0] count2, count5;\n    reg [9:0] i;\n    \n    // Power computation registers\n    reg [9:0] exponent;\n    reg [9:0] power_result;\n    reg [9:0] base_power;\n    reg [9:0] power_temp;\n    \n    // Functions to remove factors of 2 and 5\n    function automatic [9:0] remove_2s(input [9:0] num, output [9:0] count);\n        reg [9:0] temp;\n        integer j;\n        begin\n            temp = num;\n            count = 10'd0;\n            for (j = 0; j < 10; j = j + 1) begin\n                if (temp[0] == 1'b0) begin\n                    temp = temp >> 1;\n                    count = count + 10'd1;\n                end\n            end\n            remove_2s = temp;\n        end\n    endfunction\n    \n    function automatic [9:0] remove_5s(input [9:0] num, output [9:0] count);\n        reg [9:0] temp;\n        integer j;\n        begin\n            temp = num;\n            count = 10'd0;\n            for (j = 0; j < 5; j = j + 1) begin\n                if ((temp % 5) == 0) begin\n                    temp = temp / 5;\n                    count = count + 10'd1;\n                end\n            end\n            remove_5s = temp;\n        end\n    endfunction\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 10'd0;\n            done <= 1'b0;\n            product <= 14'd1;\n            count2 <= 10'd0;\n            count5 <= 10'd0;\n            i <= 10'd0;\n            base_power <= 10'd0;\n            power_temp <= 10'd0;\n            power_result <= 10'd0;\n            exponent <= 10'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        product <= 14'd1;\n                        count2 <= 10'd0;\n                        count5 <= 10'd0;\n                        i <= 10'd1;\n                        state <= FACT_LOOP;\n                    end\n                end\n                \n                FACT_LOOP: begin\n                    if (i <= n) begin\n                        // Process i\n                        reg [9:0] cnt2_i, cnt5_i;\n                        reg [9:0] residue_i;\n                        residue_i = remove_2s(i, cnt2_i);\n                        residue_i = remove_5s(residue_i, cnt5_i);\n                        product <= (product * residue_i) % 14'd10000;\n                        count2 <= count2 + cnt2_i;\n                        count5 <= count5 + cnt5_i;\n                    end\n                    \n                    if (i + 10'd1 <= n) begin\n                        // Process i+1\n                        reg [9:0] cnt2_i1, cnt5_i1;\n                        reg [9:0] residue_i1;\n                        residue_i1 = remove_2s(i + 10'd1, cnt2_i1);\n                        residue_i1 = remove_5s(residue_i1, cnt5_i1);\n                        product <= (product * residue_i1) % 14'd10000;\n                        count2 <= count2 + cnt2_i1;\n                        count5 <= count5 + cnt5_i1;\n                    end\n                    \n                    if (i >= n) begin\n                        state <= POWER_PREP;\n                    end else begin\n                        i <= i + 10'd2;\n                    end\n                end\n                \n                POWER_PREP: begin\n                    exponent <= count2 - count5;\n                    power_result <= 10'd1;\n                    base_power <= 10'd2;\n                    power_temp <= count2 - count5;\n                    state <= POWER_LOOP;\n                end\n                \n                POWER_LOOP: begin\n                    if (power_temp > 10'd0) begin\n                        if (power_temp[0]) begin\n                            power_result <= (power_result * base_power) % 10'd1000;\n                        end\n                        base_power <= (base_power * base_power) % 10'd1000;\n                        power_temp <= power_temp >> 1;\n                    end else begin\n                        state <= MULTIPLY;\n                    end\n                end\n                \n                MULTIPLY: begin\n                    result <= (product[9:0] * power_result) % 10'd1000;\n                    done <= 1'b1;\n                    state <= FINISH;\n                end\n                \n                FINISH: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n    \nendmodule